changeSet.sql:
UPDATE surcharge_policy
SET cod_tiers_json = '[{"minAmount":0,"maxAmount":2000000,"feeAmount":30000,"feePercent":null},{"minAmount":2000000,"maxAmount":5000000,"feeAmount":40000,"feePercent":null},{"minAmount":5000000,"maxAmount":10000000,"feeAmount":60000,"feePercent":null},{"minAmount":10000000,"maxAmount":15000000,"feeAmount":80000,"feePercent":null},{"minAmount":15000000,"maxAmount":20000000,"feeAmount":100000,"feePercent":null},{"minAmount":20000000,"maxAmount":null,"feeAmount":null,"feePercent":1}]'
WHERE cod_tiers_json IS NULL OR TRIM(cod_tiers_json) = '';
